class Solution {
public:
    vector<vector<int>> getAncestors(int n, vector<vector<int>>& edges) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) adj[e[0]].push_back(e[1]);
        vector<vector<int>> res(n);
        for (int src = 0; src < n; src++) {
            vector<bool> visited(n, false);
            function<void(int)> dfs = [&](int u) {
                for (int v : adj[u]) {
                    if (!visited[v]) {
                        visited[v] = true;
                        res[v].push_back(src);
                        dfs(v);
                    }
                }
            };
            dfs(src);
        }
        return res;
    }
};

class Solution {
    public List<List<Integer>> getAncestors(int n, int[][] edges) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) adj[e[0]].add(e[1]);
        List<List<Integer>> res = new ArrayList<>();
        for (int i = 0; i < n; i++) res.add(new ArrayList<>());
        for (int src = 0; src < n; src++) {
            boolean[] visited = new boolean[n];
            dfs(src, src, adj, visited, res);
        }
        return res;
    }
    private void dfs(int src, int u, List<Integer>[] adj, boolean[] visited, List<List<Integer>> res) {
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                res.get(v).add(src);
                dfs(src, v, adj, visited, res);
            }
        }
    }
}

var getAncestors = function(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) adj[u].push(v);
    const res = Array.from({ length: n }, () => []);
    for (let src = 0; src < n; src++) {
        const visited = new Uint8Array(n);
        const dfs = (u) => {
            for (const v of adj[u]) {
                if (!visited[v]) {
                    visited[v] = 1;
                    res[v].push(src);
                    dfs(v);
                }
            }
        };
        dfs(src);
